from pathlib import Path
import json,csv
R=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def table(name):
 with (R/'tables'/f'{name}.csv').open(encoding='utf-8') as f:return list(csv.DictReader(f))
def main():
 c=read(R/'reports/analysis-context.json');s=[r for r in c['summary'] if r['task']=='all'];n=[r for r in c['neutral'] if r['task']=='all'];q=[r for r in c['quality'] if r['task']=='all'];a=c['audit'];cfg=read(R/'config/formal-protocol.json');meta=read(R/'run_meta.json')
 lines=['# E 组正式结果','', f"已完成960轮、15000次完整正式模型请求；另有{a['diagnostic_model_requests_excluded']}次诊断/中断请求保留并排除正式配对统计。HotpotQA/TriviaQA各30条真实query，N5/20，8臂；冷首请求、带外盐、原生输入IDs与引擎cached计数全量审计通过。",'', '## 表 E-I（任务合并；每格60个query组）','', '| Arm | N | Warm hit | Mean CAF (f=.1) | 95% query-group CI |','|---|---:|---:|---:|---|']
 lines +=[f"| {r['arm']} | {r['N']} | {r['warm_hit_mean']:.3%} | {r['CAF_mean']:.6f} | [{r['CAF_CI_low']:.6f}, {r['CAF_CI_high']:.6f}] |" for r in s]
 lines +=['', '所有CAF使用同query、同N、同管线良性分母。FunctionTool工具调用生成+反思回答两请求均计费；不能借用前置检索分母。主表是每query配对CAF的均值；CSV另保留f=.25/.5、query分布和每副本计量。','', '## 中性对照与置信区间','', 'bootstrap以query为组保留整个N副本，10000次、seed42、percentile95%；逐任务/逐N与合并结果全部报告。没有中心化、挑选样本、重设阈值或人为扩CI。','', '| Arm | N | 95% CI跨越1? |','|---|---:|---|']
 lines +=[f"| {r['arm']} | {r['N']} | {r['CAF_CI_crosses_1']} |" for r in n]
 lines +=['', '区间若不跨1，不能仍称统计噪声：固定标记改变输入长度及16-token块对齐，可以产生小而可分辨的CAF偏移；原始点估计/CI照报。高复用且无跨副本返回方差的机制中性，与CAF必须精确为1是不同主张。','', '## QA完整回答与配对边界','', '| Arm | N | EM | F1 | 配对F1差 | 95% CI |','|---|---:|---:|---:|---|']
 lines +=[f"| {r['arm']} | {r['N']} | {r['em_mean']:.3%} | {r['f1_mean']:.3%} | {r['f1_paired_difference']:.6f} | [{r['f1_difference_CI_low']:.6f}, {r['f1_difference_CI_high']:.6f}] |" for r in q]
 lines +=['', 'HotpotQA采用原生规范化、yes/no/noanswer特例、max over gold EM/F1；TriviaQA标点替换为空白含弯引号，max over aliases。按同一query配对，原始多数投票平票用最先副本；贪心T0/seed42，max_tokens2048对齐T，任何截断均停止核查，不将截断答案纳入完成轮。只报告置信区间界限，未检出差异不是等效。','', '重要限制：小索引固定132 passage/3 context，而正式查询来自60份原任务context；多数query原始context并不在当前索引中。必须同时阅读绝对基线准确率与original_context_retrieved_fraction，不能用低准确率/UNKNOWN背景中的零差异强称广泛语义隐蔽性。答案来源覆盖与错误分布在逐query表披露；引用答案未加入向量库。','', '## 投递、构造与因果范围','', 'E-E2=应用侧每副本独立CPU编码+真实FAISS检索，在生成前返回，grounding-first把G置于S之前，之后真实AutoGen AssistantAgent生成。零宽/metadata由检索函数返回边界产生，装配器只复制；原始返回、顶k、输入、分叉字符与原生token LCP、分叉前UTF-8相同性均落盘。静态臂所有存储passage带同一个常量标记，属于较强的受控语料干预，不冒称单篇静态文档的攻击者主动行为。','', 'realizability仅覆盖§III所引grounding-first+逐副本独立检索模式的一条受控实现。A2每副本独立和生成前调用、A3前置均实测成立；不外推部署比例，部署普遍性须由A2/A3扫描负责并写入Limitations。','', '## E-E5 部署侧条件性','', '静态检索原始返回在同query各副本完全一致；应用部署renderer在第一条完整passage ID之后插入逐副本元数据。因此保留首passage共同前缀，分歧来自部署渲染，不是攻击者静态标记主动制造方差。诊断首轮误把段落分隔符当passage边界，已移至interrupted并排除；修正到事前规定的passage-ID位置，不因CAF观测择点。','', '## E-E6 原生调用位置边界','', '相同RetrievalService.retrieve绑定原合法query，经原生FunctionTool，由模型生成工具调用→AutoGen执行→reflect_on_tool_use=True第二次模型回答；不是在宿主直接代造assistant tool_call。首次默认auto选择没有调用工具，原响应保留为单独边界。为观察实际append位置，后续E6明确使用“显式选择唯一search_documents Tool对象”的调用策略；不能称默认AutoGen自主调用成功或隐藏该条件。工具JSON参数、tool_call_id、真实返回和两请求全部存档。','', 'AutoGen0.7.5专用tool_choice会覆盖extra_create_args中的同名设置，接口诊断已保留。Llama模板把role:tool内容转为ipython角色的JSON字符串，新行成为转义；原始role:tool字符串保持原返回，最终实际输入IDs保留。不能把宿主原字节等同原生template字节，也不能宣称规范化仍保留原样不可见表示。','', 'S位于原生工具结果之前，属于append边界。初始用户消息尾部的副本编号也在G之前，已使良性晚G不能跨副本复用，所以额外nonce可能几乎不增损；这是当前原生构造“无额外塌陷”的原因之一，不能误称已测出G区域一定可复用。E6自己的两请求良性CAF分母保留此成本。','', '## 环境、单点历史与限制','', '一律称“受控应用历史(2000-token 合成共享历史)”，S保持旧E5单点，不暗示真实用户会话；随会话长度的CAF依赖成本模型/E5-append，当前E没有S长度扫描。受控索引132 passage/3 context、精确FAISS IndexFlatIP/top-k6，CPU torch deterministic/单线程、稳定chunk ID打破同分，GPU嵌入排名波动已排除。相同query跨每轮所有调用的嵌入hash/top-k ID及顺序一致。', '', f"vLLM启动：`{meta['service_launch']['args']}`；served alias llama-3.3-70b，原生响应canonical Llama-3.3-70B-Instruct，以启动权重路径和实际usage为准。嵌入all-MiniLM-L6-v2下载模块+权重逐文件SHA固定，mirror master版本以SHA256锁定，不把master视为不可变tag；Transformers/Torch/FAISS/AutoGen版本见client-environment.json。", '', '所有旧资产仅只读，句向量权重按用户授权保存LLM-Model；其他E文件仅写E。云端无联网下载、未新装系统库；运行缓存归E。阶段闸、原始预注册、初始冻结、修订说明、失败原请求不覆盖。正式判断未事后修改；工具调用策略和E5位置修复属于公开披露的工程修订，E2主构造不变。当前结果不清理论文TODO、不写入论文源，入稿需用户复核。','', '## 逐假设事实与边界','']
 lines +=[f"- {key}: `{json.dumps(value,ensure_ascii=False)}`" for key,value in c['conclusions'].items()]
 (R/'reports/E_full_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 summary=['# E 正式结果摘要','',lines[2],'', '| Arm | N | Hit | CAF [95% CI] |','|---|---:|---:|---|']+[f"| {r['arm']} | {r['N']} | {r['warm_hit_mean']:.3%} | {r['CAF_mean']:.4f} [{r['CAF_CI_low']:.4f}, {r['CAF_CI_high']:.4f}] |" for r in s]
 summary +=['', '完整结果与中性CI是否跨1、配对QA差、绝对基线质量、小索引覆盖、原生auto无调用及required策略限制见 reports/E_full_report.md。受控应用历史(2000-token 合成共享历史)、132 passage/3 context，不暗示真实会话或web-scale；普遍性归A2/A3扫描。E-E5仅部署侧条件性；E-E6两请求独立良性分母、append无额外塌陷如实报。未改论文源。']
 (R/'E_results_summary.md').write_text('\n'.join(summary)+'\n',encoding='utf-8')
 # Reusable table fragments; no standalone manuscript modified.
 def esc(v):return str(v).replace('_',r'\_').replace('%',r'\%')
 tex=[r'% Requires graphicx',r'\begin{table*}[t]',r'\centering',r'\caption{Controlled end-to-end RAG delivery: 60 queries per pooled stratum.}',r'\resizebox{\textwidth}{!}{\begin{tabular}{lrrrrr}',r'\hline Arm & N & Warm hit & CAF & CI low & CI high \\',r'\hline']
 tex +=[f"{esc(r['arm'])} & {r['N']} & {r['warm_hit_mean']:.5f} & {r['CAF_mean']:.5f} & {r['CAF_CI_low']:.5f} & {r['CAF_CI_high']:.5f}"+r' \\' for r in s];tex +=[r'\hline\end{tabular}}',r'\par\scriptsize Query-group bootstrap (10000 resamples); native two-request arms use their own benign denominator. Fixed 132-passage index and 2000-token synthetic controlled history, not deployment prevalence.',r'\end{table*}'];(R/'tables/E-I.tex').write_text('\n'.join(tex)+'\n',encoding='utf-8')
 print('E reports written')
if __name__=='__main__':main()
